# Text of a PDF statement. PDFs generated by the bank carry their text and are read directly;
# scanned PDFs (only images inside) go through OCR.
class StatementParser::Pdf
  MIN_TEXT_LENGTH = 50

  def initialize(bytes, password: nil)
    @bytes = bytes
    @password = password.presence
  end

  def text
    reader = PDF::Reader.new(StringIO.new(@bytes), **{ password: @password }.compact)
    text = reader.pages.map(&:text).join("\n\f\n")
    text.gsub(/\s/, "").length >= MIN_TEXT_LENGTH ? text : StatementParser::Ocr.pdf(@bytes)
  rescue PDF::Reader::EncryptedPDFError
    message = @password ? "Senha do PDF incorreta." : "Este PDF é protegido por senha. Informe a senha no campo abaixo do arquivo."
    raise StatementParser::Error, message
  rescue StatementParser::Error
    raise
  rescue StandardError => e # pdf-reader raises many internal errors on damaged or unusual files
    Rails.logger.warn("[StatementParser::Pdf] #{e.class}: #{e.message}")
    raise StatementParser::Error, "Não foi possível ler este PDF."
  end
end
